// RunJSONSerializationTestForRouteFilter_Spec runs a test to see if a specific instance of RouteFilter_Spec round trips to JSON and back losslessly
func RunJSONSerializationTestForRouteFilter_Spec(subject RouteFilter_Spec) string {
	// Serialize to JSON
	bin, err := json.Marshal(subject)
	if err != nil {
		return err.Error()
	}

	// Deserialize back into memory
	var actual RouteFilter_Spec
	err = json.Unmarshal(bin, &actual)
	if err != nil {
		return err.Error()
	}

	// Check for outcome
	match := cmp.Equal(subject, actual, cmpopts.EquateEmpty())
	if !match {
		actualFmt := pretty.Sprint(actual)
		subjectFmt := pretty.Sprint(subject)
		result := diff.Diff(subjectFmt, actualFmt)
		return result
	}

	return ""
}

// Generator of RouteFilter_Spec instances for property testing - lazily instantiated by RouteFilter_SpecGenerator()
var routeFilter_SpecGenerator gopter.Gen

// RouteFilter_SpecGenerator returns a generator of RouteFilter_Spec instances for property testing.
// We first initialize routeFilter_SpecGenerator with a simplified generator based on the
// fields with primitive types then replacing it with a more complex one that also handles complex fields
// to ensure any cycles in the object graph properly terminate.
func RouteFilter_SpecGenerator() gopter.Gen {
	if routeFilter_SpecGenerator != nil {
		return routeFilter_SpecGenerator
	}

	generators := make(map[string]gopter.Gen)
	AddIndependentPropertyGeneratorsForRouteFilter_Spec(generators)
	routeFilter_SpecGenerator = gen.Struct(reflect.TypeOf(RouteFilter_Spec{}), generators)

	// The above call to gen.Struct() captures the map, so create a new one
	generators = make(map[string]gopter.Gen)
	AddIndependentPropertyGeneratorsForRouteFilter_Spec(generators)
	AddRelatedPropertyGeneratorsForRouteFilter_Spec(generators)
	routeFilter_SpecGenerator = gen.Struct(reflect.TypeOf(RouteFilter_Spec{}), generators)

	return routeFilter_SpecGenerator
}

